import{_ as o,l as i,o as e,c as n,v as r,p as l,x as s,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"递归与迭代","description":"","frontmatter":{"title":"递归与迭代","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dns-recursive.md","filePath":"cs/dns-recursive.md","lastUpdated":1789023840000}'),E={name:"cs/dns-recursive.md"};function h(T,a,_,u,A,m){const t=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="递归与迭代" tabindex="-1">递归与迭代 <a class="header-anchor" href="#递归与迭代" aria-label="Permalink to &quot;递归与迭代&quot;">​</a></h1><div class="epigraph"><p>存根解析器只问一台递归服务器；递归服务器替它走完从根到权威的迭代，并把答案缓存。</p><footer>—— 据 Mockapetris, RFC 1034；Kurose and Ross 对解析模式的整理</footer></div><p><a href="/cs/dns">上一课</a>给出层次名字与「从根到权威」。本课不重画区的树。缺口是谁去问：主机上的存根几乎总把完整问题交给递归解析器；递归解析器对根、TLD、权威做<strong>迭代</strong>查询（答「去问那边」），直到得到答案或失败。本课不把记录类型表写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/dns">DNS</a> 留下解析步骤。若每台笔记本自己从根迭代，根流量与延迟都不可接受，缓存也无法共享。<a href="/cs/dhcp-nat">DHCP</a> 交出的正是递归服务器地址。递归：对客户负责完整答案；迭代：服务器之间用转介把问题推向下一级。缺口是<strong>两种查询角色</strong>，不是 HTTP。</p><p><span class="marginnote">缓存带 TTL。权威才是该区的真相；递归缓存过期后必须再走迭代。DNSSEC 是认证，后课安全再谈，本课只钉解析路径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>存根 → 递归（递归标志）。递归若缓存命中则直接答；否则从根提示开始：问，得 NS 转介，再问，直到权威的应答。迭代服务器不替对方追问。失败：名字不存在、超时、截断改 TCP，本课不把全部 RCODE 背完。</p>',8)),(e(),l(p,null,{default:s(()=>[c(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20STUB%5B%22%E5%AD%98%E6%A0%B9%22%5D%20--%3E%20REC%5B%22%E9%80%92%E5%BD%92%E8%A7%A3%E6%9E%90%E5%99%A8%22%5D%0A%20%20REC%20--%3E%20ROOT%5B%22%E9%97%AE%E6%A0%B9%E5%BE%97%E8%BD%AC%E4%BB%8B%22%5D%0A%20%20ROOT%20--%3E%20TLD%5B%22%E9%97%AE%20TLD%22%5D%0A%20%20TLD%20--%3E%20AUTH%5B%22%E9%97%AE%E6%9D%83%E5%A8%81%E5%BE%97%E7%AD%94%E6%A1%88%22%5D%0A%20%20AUTH%20--%3E%20REC%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>递归把「层次查找」收成对应用透明的一次往返（加上缓存）。它与 <a href="/cs/lpm">LPM</a> 不同：DNS 是应用层名字，IP 前缀是定位。端到端：解析错误会把 TCP 连到错误地址，TLS 证书名检查是后课补的真实性，本课只得到「一套记录」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 DoH/DoT 当主干必选，不引入根密钥典礼。答案里到底是地址还是别的对象，下一课资源记录类型。</p><p>后课默认：存根依赖递归；递归走迭代并缓存。记录类型决定答案含义。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>递归对客户负责；服务器之间迭代转介。</li><li>缓存按 TTL，真相在权威。</li><li>记录类型下一课。</li><li>出处：RFC 1034；Kurose and Ross。</li></ul>',7))])}const B=o(E,[["render",h]]);export{f as __pageData,B as default};
